import type { Request, Response } from "express";
import { randomUUID } from "node:crypto";
import { AppError } from "../../utils/appError.js";
import type { TestResource } from "../../types/api.js";

const testStore = new Map<string, TestResource>();

export const listTestsController = (_req: Request, res: Response) => {
  res.status(200).json({
    data: Array.from(testStore.values())
  });
};

export const getTestController = (req: Request, res: Response) => {
  const resource = testStore.get(req.params.id);

  if (!resource) {
    throw new AppError(404, "Test resource not found");
  }

  res.status(200).json({ data: resource });
};

export const createTestController = (req: Request, res: Response) => {
  const now = new Date().toISOString();
  const id = randomUUID();

  const resource: TestResource = {
    id,
    name: req.body.name,
    active: req.body.active ?? true,
    createdAt: now,
    updatedAt: now
  };

  testStore.set(id, resource);

  res.status(201).json({ data: resource });
};

export const updateTestController = (req: Request, res: Response) => {
  const existingResource = testStore.get(req.params.id);

  if (!existingResource) {
    throw new AppError(404, "Test resource not found");
  }

  const updatedResource: TestResource = {
    ...existingResource,
    ...req.body,
    updatedAt: new Date().toISOString()
  };

  testStore.set(existingResource.id, updatedResource);

  res.status(200).json({ data: updatedResource });
};

export const deleteTestController = (req: Request, res: Response) => {
  const exists = testStore.has(req.params.id);

  if (!exists) {
    throw new AppError(404, "Test resource not found");
  }

  testStore.delete(req.params.id);

  res.status(204).send();
};

import type { NextFunction, Request, Response } from "express";
import type { ApiErrorShape } from "../types/api.js";
import { AppError } from "../utils/appError.js";
import { logger } from "../config/logger.js";

export const errorHandler = (
  err: unknown,
  _req: Request,
  res: Response<ApiErrorShape>,
  _next: NextFunction
) => {
  if (err instanceof AppError) {
    if (err.statusCode >= 500) {
      logger.error(err.message, err.details);
    }

    return res.status(err.statusCode).json({
      statusCode: err.statusCode,
      message: err.message,
      details: err.details
    });
  }

  logger.error("Unhandled server error", err);

  return res.status(500).json({
    statusCode: 500,
    message: "Internal server error"
  });
};

import type { NextFunction, Request, Response } from "express";
import type { ApiErrorShape } from "../types/api.js";
import { AppError } from "../utils/appError.js";
import { logger } from "../config/logger.js";
import { getErrorDetails } from "../utils/errorDetails.js";

export const errorHandler = (
  err: unknown,
  _req: Request,
  res: Response<ApiErrorShape>,
  _next: NextFunction
) => {
  if (err instanceof AppError) {
    if (err.statusCode >= 500) {
      logger.error(err.message, err.details);
    }

    return res.status(err.statusCode).json({
      statusCode: err.statusCode,
      message: err.message,
      details: err.details
    });
  }

  const errorDetails = getErrorDetails(err);
  logger.error("Unhandled server error", errorDetails);

  return res.status(500).json({
    statusCode: 500,
    message: "Internal server error"
  });
};

import { Router } from "express";
import {
  createTestController,
  deleteTestController,
  getTestController,
  listTestsController,
  updateTestController
} from "../../controllers/test/test.controller.js";
import { validate } from "../../middleware/validate.js";
import {
  createTestSchema,
  testParamsSchema,
  updateTestSchema
} from "../../schemas/test/test.schema.js";

export const testRouter = Router();

testRouter.get("/", listTestsController);
testRouter.get("/:id", validate({ params: testParamsSchema }), getTestController);
testRouter.post("/", validate({ body: createTestSchema }), createTestController);
testRouter.put(
  "/:id",
  validate({ params: testParamsSchema, body: updateTestSchema }),
  updateTestController
);
testRouter.delete("/:id", validate({ params: testParamsSchema }), deleteTestController);

import { z } from "zod";

export const testParamsSchema = z.object({
  id: z.string().min(1)
});

export const createTestSchema = z.object({
  name: z.string().trim().min(1).max(100),
  active: z.boolean().default(true)
});

export const updateTestSchema = createTestSchema.partial().refine(
  (value) => Object.keys(value).length > 0,
  "At least one field must be provided"
);

import { callStructuredOpenAI } from './openai.service.js';
import { classificationBatchSchema } from '../../schemas/news/aiPipelineLoader.schemas.js';
import type { CandidateStory, ClassificationItem } from '../../schemas/news/aiPipelineLoader.schemas.js';

// ─── Constants ────────────────────────────────────────────────────────────────

const CLASSIFIER_MODEL = 'gpt-6-luna';

// ─── Public API ───────────────────────────────────────────────────────────────

/**
 * Classifies a batch of raw candidate stories for legitimacy, duplication,
 * and sub-topic tagging using a low-cost nano model.
 * Returns one ClassificationItem per candidate, keyed by candidateIndex.
 */
export async function classifyCandidates(
  candidates: CandidateStory[],
  topicLabel: string,
): Promise<ClassificationItem[]> {
  const candidateList = candidates
    .map(
      (candidate, index) =>
        `${index}. [${candidate.sourceDomain}] "${candidate.title}"\n   Excerpt: "${candidate.snippet}"`,
    )
    .join('\n');

  const result = await callStructuredOpenAI({
    model: CLASSIFIER_MODEL,
    messages: [
      {
        role: 'system',
        content:
          'You are a news quality classifier. You evaluate news article candidates for source credibility' +
          ' and determine whether articles in a batch are substantively duplicating each other.',
      },
      {
        role: 'developer',
        content:
          'Respond ONLY in the specified JSON format.' +
          ' For every candidate (identified by its numeric index), provide:' +
          ' - candidateIndex: the index number as shown.' +
          ' - legitimacyScore: 0.0–1.0 rating of how credible and factually reliable this source and story appears.' +
          ' - isDuplicate: true ONLY if this article is substantively identical to a lower-indexed article already in the list.' +
          ' - subTopic: a concise tag for the specific sub-topic (e.g. "supreme court ruling", "box office results").' +
          ' You must return exactly one classification per candidate index — no omissions.',
      },
      {
        role: 'user',
        content: `Classify the following ${topicLabel} news article candidates:\n\n${candidateList}`,
      },
    ],
    batchSchema: classificationBatchSchema,
    batchSchemaName: 'classification_batch',
  });

  return result.classifications;
}

